sys_variable_value.value:
(function execute(inputs, outputs) {
var currentStock = parseFloat(inputs.schedule_record.u_stock_quantity); 
if (currentStock <= 0) { 
// Guard: never deduct below zero 
outputs.new_stock = 0; 
outputs.error = 'Stock already at zero — deduction skipped.'; 
} else { 
outputs.new_stock = currentStock - 1; 
outputs.error = ''; 
}
})(inputs, outputs);

